onumber  egin{split} &\qquad rac{1}{	ilde{N}^{2}}\Bigl\vert\sum_{\alpha\in R_{N}/p\cap R_{N}/q}f(p\alpha)\overline{f}(q\alpha)\Bigr\vert \leq rac{1}{{	ilde{N}^{2}}}\sum_{j=-2N}^{2N}\Bigl\vert\sum_{\alpha\in U_{j}}f(p\alpha)\overline{f}(q\alpha)\Bigr\vert \&= rac{1}{{	ilde{N}^{2}}}\sum_{j=-2N}^{2N}\Bigl\vert\sum_{x=a_{j}}^{b_{j}}e(-x old{v}\circ_{N} old{\xi})e(-j old{w}\circ_{N} old{\xi}) \Bigr\vert \leq rac{1}{{	ilde{N}^{2}}}\sum_{j=-2N}^{2N}  rac{2}{\Vert  old{v}\circ_{N} old{\xi}\Vert}\leq rac{C}{N\Vert old{v}\circ_{N} old{\xi}\Vert} \end{split} \end{equation} for some universal constant $C$. On the other hand, writing $V_{j}=\{\alpha\in R_{N}/p\cap R_{N}/q\colon Re(\alpha)=i\}$, then a similar argument shows that $$ rac{1}{	ilde{N}^{2}}\Bigl\vert\sum_{\alpha\in R_{N}/p\cap R_{N}/q}f(p\alpha)\overline{f}(q\alpha)\Bigr\vert\leq rac{C}{N\Vert old{w}\circ_{N} old{\xi}\Vert}.$$ If $\vert\widehat{\chi_{N}}(\xi)\vert\geq\epsilon$, by Lemma ef{katai}, there exist $p,q\in\mathbb{P}[i], \mathcal{N}(p)<\mathcal{N}(q)<K$ such that $ rac{1}{	ilde{N}^{2}}\Bigl\vert\sum_{\alpha\in R_{N}/p\cap R_{N}/q}f(p\alpha)\overline{f}(q\alpha)\Bigr\vert\geq \delta$. Thus $\max\{\Vert old{v}\circ_{N} old{\xi}\Vert,\Vert old{w}\circ_{N} old{\xi}\Vert\}\leq  rac{C'}{N\delta}$ for some universal constant $C'$. Suppose  egin{equation}
onumber  egin{split} & old{v}\circ_{N} old{\xi}= rac{1}{	ilde{N}}((p_{1}-q_{1})\xi_{1}+(p_{2}-q_{2})\xi_{2})=a_{1}\pm\Vert old{v}\circ_{N} old{\xi}\Vert; \& old{w}\circ_{N} old{\xi}= rac{1}{	ilde{N}}((q_{2}-p_{2})\xi_{1}+(p_{1}-q_{1})\xi_{2})=a_{2}\pm\Vert old{w}\circ_{N} old{\xi}\Vert \end{split} \end{equation} for some $a_{1},a_{2}\in\mathbb{Z}$. Then $\xi_{1}/	ilde{N}=(n_{1}+\delta_{1})/\Delta, \xi_{2}/	ilde{N}=(n_{2}+\delta_{2})/\Delta$, where $\Delta=(p_{1}-q_{1})^{2}+(p_{2}-q_{2})^{2}
eq 0, n_{1},n_{2}\in\mathbb{Z}, \vert\delta_{1}\vert, \vert\delta_{2}\vert\leq rac{KC''}{N\delta}$ for some universal constant $C''$. Since $\Delta$ divides $Q$, we get $\Vert Q\xi_{i}/	ilde{N}\Vert=\Vert Q\delta_{i}/	ilde{N}\Vert\leq rac{KC''}{N\delta}$ for $i=1,2$. The corollary follows by taking $V=\lceil rac{KC''}{\delta}ceil$ (recall that $\lceil xceil$ is the smallest integer which is not smaller than $x$).

Let $\delta=\delta(\epsilon,1)$ and $K=K(\epsilon,1)$ be given by Lemma \ref{katai}. Let
    \begin{equation}\nonumber
  \begin{split}
   Q=\prod_{p,q\in\mathbb{P}[i],\mathcal{N}(p)<\mathcal{N}(q)<K}\mathcal{N}(p-q)^{2}\in\mathbb{N}.
  \end{split}
\end{equation}
Suppose that $N>K$. Let $q,p\in\mathbb{P}[i]$ with $\mathcal{N}(p)<\mathcal{N}(q)<K$ and let $\xi\in R_{\tilde{N}}$. Denote $p=p_{1}+p_{2}i,q=q_{1}+q_{2}i$. Let $\bold{v}=(p_{1}-q_{1},p_{2}-q_{2}), \bold{w}=(q_{2}-p_{2},p_{1}-q_{1})$. Let $f\colon R_{\tilde{N}}\rightarrow\mathbb{C}, f(\alpha)=e(-\alpha\circ_{N}\bold{\xi})$.

For $i\in\mathbb{Z}$, denote $U_{j}=\{\alpha\in R_{N}/p\cap R_{N}/q\colon Im(\alpha)=j\}$. Then $ R_{N}/p\cap R_{N}/q=\bigcup_{j=-2N}^{2N}U_{j}$. By the convexity of $ R_{N}/p\cap R_{N}/q$, each $U_{j}$ can be written as $U_{j}=\{x+ji\colon a_{j}\leq x\leq b_{j}\}$ for some $a_{j}, b_{j}\in\mathbb{Z}$. We have
  \begin{equation}\nonumber
  \begin{split}
   &\qquad\frac{1}{\tilde{N}^{2}}\Bigl\vert\sum_{\alpha\in R_{N}/p\cap R_{N}/q}f(p\alpha)\overline{f}(q\alpha)\Bigr\vert
   \leq\frac{1}{{\tilde{N}^{2}}}\sum_{j=-2N}^{2N}\Bigl\vert\sum_{\alpha\in U_{j}}f(p\alpha)\overline{f}(q\alpha)\Bigr\vert
   \\&=\frac{1}{{\tilde{N}^{2}}}\sum_{j=-2N}^{2N}\Bigl\vert\sum_{x=a_{j}}^{b_{j}}e(-x\bold{v}\circ_{N}\bold{\xi})e(-j\bold{w}\circ_{N}\bold{\xi}) \Bigr\vert
   \leq\frac{1}{{\tilde{N}^{2}}}\sum_{j=-2N}^{2N}
   \frac{2}{\Vert \bold{v}\circ_{N}\bold{\xi}\Vert}\leq\frac{C}{N\Vert\bold{v}\circ_{N}\bold{\xi}\Vert}
  \end{split}
\end{equation}
for some universal constant $C$.

Suppose
  \begin{equation}\nonumber
  \begin{split}
   &\bold{v}\circ_{N}\bold{\xi}=\frac{1}{\tilde{N}}((p_{1}-q_{1})\xi_{1}+(p_{2}-q_{2})\xi_{2})=a_{1}\pm\Vert\bold{v}\circ_{N}\bold{\xi}\Vert;
   \\&\bold{w}\circ_{N}\bold{\xi}=\frac{1}{\tilde{N}}((q_{2}-p_{2})\xi_{1}+(p_{1}-q_{1})\xi_{2})=a_{2}\pm\Vert\bold{w}\circ_{N}\bold{\xi}\Vert
  \end{split}
\end{equation}
for some $a_{1},a_{2}\in\mathbb{Z}$. Then
$\xi_{1}/\tilde{N}=(n_{1}+\delta_{1})/\Delta, \xi_{2}/\tilde{N}=(n_{2}+\delta_{2})/\Delta$,
where $\Delta=(p_{1}-q_{1})^{2}+(p_{2}-q_{2})^{2}\neq 0, n_{1},n_{2}\in\mathbb{Z}, \vert\delta_{1}\vert, \vert\delta_{2}\vert\leq\frac{KC''}{N\delta}$ for some universal constant $C''$.

For every $\epsilon>0$, define

  \begin{equation}\nonumber
  \begin{split}
   &\mathcal{A}(N,\epsilon)=\Bigl\{\bold{\xi}\in R_{\tilde{N}}\colon \sup_{\chi\in\mathcal{M}_{\mathbb{Z}[i]}}\vert\widehat{\chi_{N}}(\bold{\xi})\vert\geq\epsilon^{2}\Bigr\};
   \\&W(N,q,\epsilon)=\max_{\bold{\xi}=\xi_{1}+\xi_{2}i\in\mathcal{A}(N,\epsilon)}\max_{i=1,2}N\Vert q\xi_{i}/\tilde{N}\Vert;
   \\&Q(\epsilon)=\min_{k\in\mathbb{N}}\Bigl\{k!\colon\limsup_{N\rightarrow\infty}W(N,k!,\epsilon)<\infty\Bigr\};
   \\&V(\epsilon)=1+\Bigl\lfloor \frac{1}{Q(\epsilon)}\limsup_{N\rightarrow\infty}W(N,Q(\epsilon),\epsilon)\Bigr\rfloor.
  \end{split}
\end{equation}

For every $m\geq 1, N>2m$, we define the function $f_{N,m}\colon R_{\tilde{N}}\rightarrow\mathbb{C}$ by

  \begin{equation}\nonumber
  \begin{split}
   f_{N,m}(\alpha)=\sum_{-m\leq\xi_{1}\leq m}\sum_{-m\leq\xi_{2}\leq m}(1-\frac{\vert\xi_{1}\vert}{m})(1-\frac{\vert\xi_{2}\vert}{m})e(\alpha\circ_{N}(\bold{\xi}_{1}+\bold{\xi}_{2}i)).
  \end{split}
\end{equation}

For $N>4Q(\epsilon)V(\epsilon)\lceil\epsilon^{-4}\rceil$, we define

  \begin{equation} \begin{split}
   \phi_{N,\epsilon}(x+yi)=f_{N,2Q(\epsilon)V(\epsilon)\lceil\epsilon^{-4}\rceil}(Q_{\tilde{N}}(\epsilon)^{*}(x+yi)).
  \end{split}
\end{equation}

In other words, $f_{N,2Q(\epsilon)V(\epsilon)\lceil\epsilon^{-4}\rceil}(x+yi)=\phi_{N,\epsilon}(Q(\epsilon)(x+yi))$.

Then $\phi_{N,\epsilon}$ is also a kernel of $R_{\tilde{N}}$, and the spectrum of $\phi_{N,\epsilon}$ is the set

  \begin{equation}\nonumber
  \begin{split}
   \Xi_{N,\epsilon}=\Bigl\{\bold{\xi}=\xi_{1}+\xi_{2}i\in R_{\tilde{N}}\colon\Bigl\Vert\frac{Q(\epsilon)\xi_{i}}{\tilde{N}}\Bigr\Vert<\frac{2Q(\epsilon)V(\epsilon)\lceil\epsilon^{-4}\rceil}{\tilde{N}}, i=1,2\Bigr\},
  \end{split}
\end{equation}
and we have $\widehat{\phi_{N,\epsilon}}(\bold{\xi})=\Bigl(1-\Bigl\Vert\frac{Q(\epsilon)\xi_{1}}{\tilde{N}}\Bigr\Vert\frac{\tilde{N}}{2Q(\epsilon)V(\epsilon)\lceil\epsilon^{-4}\rceil}\Bigr)
            \Bigl(1-\Bigl\Vert\frac{Q(\epsilon)\xi_{2}}{\tilde{N}}\Bigr\Vert\frac{\tilde{N}}{2Q(\epsilon)V(\epsilon)\lceil\epsilon^{-4}\rceil}\Bigr)$ if $\bold{\xi}\in\Xi_{N,\epsilon}$ and $\widehat{\phi_{N,\epsilon}}(\bold{\xi})=0$ otherwise.

Thus by identity (\ref{F}), we have
    \begin{equation}\nonumber
  \begin{split}
  &\qquad \Vert\chi_{N,u}\Vert_{U^{2}(R_{\tilde{N}})}^{4}=\sum_{\bold{\xi}\in R_{\tilde{N}}}\vert\widehat{\chi_{N}}(\bold{\xi})-\widehat{\phi_{N,\epsilon}*\chi_{N}}(\bold{\xi})\vert^{4}\leq\epsilon^{4}\sum_{\bold{\xi}\in R_{\tilde{N}}}\vert\widehat{\chi_{N}}(\bold{\xi})-\widehat{\phi_{N,\epsilon}*\chi_{N}}(\bold{\xi})\vert^{2}
  \\&\leq\sum_{\bold{\xi}\in R_{\tilde{N}}}\vert\widehat{\chi_{N}}(\bold{\xi})\vert^{2}\leq\epsilon^{4},
  \end{split}
\end{equation}
where the last estimate follows from Parseval's identity. This proves (ii).

Lastly, using Fourier inversion formula and the estimate $\vert e(x)-1\vert\leq 2\pi\Vert x\Vert$, we get
    \begin{equation}\nonumber
  \begin{split}
  &\vert\chi_{N,s}(\alpha+Q)-\chi_{N,s}(\alpha)\vert\leq\sum_{\bold{\xi}=\xi_{1}+\xi_{2}i\in R_{\tilde{N}}}\vert\widehat{\phi_{N,\epsilon}}(\bold{\xi})\vert\cdot 2\pi\Bigl\Vert\frac{Q\xi_{1}}{\tilde{N}}\Bigr\Vert
  \leq\vert\Xi_{N,\epsilon}\vert\cdot\frac{4\pi QV\lceil\epsilon^{-4}\rceil}{\tilde{N}};
  \\& \vert\chi_{N,s}(\alpha+Qi)-\chi_{N,s}(\alpha)\vert\leq\sum_{\bold{\xi}=\xi_{1}+\xi_{2}i\in R_{\tilde{N}}}\vert\widehat{\phi_{N,\epsilon}}(\bold{\xi})\vert\cdot 2\pi\Bigl\Vert\frac{Q\xi_{2}}{\tilde{N}}\Bigr\Vert
  \leq\vert\Xi_{N,\epsilon}\vert\cdot\frac{ 4\pi QV\lceil\epsilon^{-4}\rceil}{\tilde{N}}.
  \end{split}
\end{equation}

We implicitly assume that $G$ is endowed with a \emph{Mal'cev basis} $\mathcal{X}$, meaning $\mathcal{X}$ is a basis $(\xi_{1},\dots,\xi_{m})$ of the Lie algebra $\mathfrak{g}$ of $G$ that has the following properties:

(i) The map $\phi\colon \mathbb{R}^{m}\rightarrow G$ given by
\begin{equation}\nonumber
  \begin{split}
    \phi(t_{1},\dots,\xi_{m})=\exp(t_{1}\xi_{1})\cdot\ldots\cdot\exp(t_{m}\xi_{m})
  \end{split}
\end{equation}
is a homeomorphism from $\mathbb{R}^{m}$ onto $G$;

(ii) $G_{2}=\phi(\{0\}^{s}\times\mathbb{R}^{r})$;

(iii) $\Gamma=\phi(\mathbb{Z}^{m})$.

Let the space $X=G/\Gamma$ be endowed with the quotient metric $d_{X}$. Writing $p\colon G\rightarrow X$ for the quotient map, the metric $d_{X}$ is defined by
    \begin{equation}\nonumber
  \begin{split}
  d_{X}(x,y)=\inf_{g,h\in G}\{d_{G}(g,h)\colon p(g)=x, p(h)=y\}.
  \end{split}
\end{equation}

By Lemma \ref{2p}, we can write
\begin{equation}\nonumber
  \begin{split}
  g'(m,n)=g_{0}g_{1,1}^{m}g_{1,2}^{n}g_{2,1}^{\binom{m}{2}}g_{2,2}^{mn}g_{2,3}^{\binom{n}{2}}
  \end{split}
\end{equation}
for some $g_{0}, g_{1,1}, g_{1,2}\in G, g_{2,1},g_{2,2},g_{2,3}\in G_{2}$.
It remains to show that
$g_{0}, g_{1,1}, g_{1,2}\in G'$, $g_{2,1},g_{2,2},g_{2,3}\in G'_{2}$
for case (ii).

Denote
$$\partial_{(x,y)}g(m,n)=g(m+x,n+y)g(m,n)^{-1}.$$ Since $G$ is of order 2,
$G_{2}$ is included in the center of $G$. Therefore, we obtain
\begin{equation}\nonumber
  \begin{split}
  \partial_{(1,0)}g''(m,0)=g_{1,1}g_{2,1}^{m} \text{ and }
  \partial_{(1,0)}^{2}g''(m,0)=g_{2,1}.
  \end{split}
\end{equation}
It follows that $g_{1,1},g_{2,1}\in G'$. Similarly,
$g_{1,2},g_{2,3}\in G'$.

