By Lemma \ref{dege}, each subgroup $H$ of $H_{0}$ must be one of the following three types:
\begin{enumerate}
    \item $[H,H]=(\{0\}^{s}\times\mathbb{R})\times(\{0\}^{s}\times\mathbb{R})$. In this case, we say that $H$ is of \emph{type 1};
    \item $[H,H]=\Bigl\{\bigl((\bold{0};\lambda_{1}t),(\bold{0};\lambda_{2}t)\bigr)\colon t\in\mathbb{R}\Bigr\}$ for some $\lambda_{1},\lambda_{2}\in\mathbb{R}$
        not all equal to 0. In this case, we say that $H$ is of \emph{type 2} for the pair $(\lambda_{1},\lambda_{2})$;
     \item $[H,H]=\{\bold{0}\}$. In this case, we say that $H$ is of \emph{type 3}, which is equivalent to saying that $H$ is abelian.
   \end{enumerate}

For any $\bold{\lambda}\in\mathbb{R}^{2},\bold{\lambda}\neq (0,0)$, if $\lambda_{1}\neq 0$, we define $\theta_{\bold{\lambda}}\colon \mathbb{R}^{2s+2}\rightarrow H_{0}$ by
   \begin{equation}\nonumber
    \begin{split}
\theta_{\bold{\lambda}}(\bold{x},\bold{y},w,z)=\Bigl((\bold{x};\lambda_{1}z),(\bold{y};\lambda_{2}z+w)\Bigr);
    \end{split}
  \end{equation}
  if $\lambda_{1}=0, \lambda_{2}\neq 0$, we define
     \begin{equation}\nonumber
    \begin{split}
\theta_{\bold{\lambda}}(\bold{x},\bold{y},w,z)=\Bigl((\bold{x};w),(\bold{y};\lambda_{2}z)\Bigr).
    \end{split}
  \end{equation}
  This defines a homeomorphism $\theta_{\bold{\lambda}}$ for all $\bold{\lambda}\neq (0,0)$.

For any element $\bold{c}\in H$, we write
     \begin{equation}\nonumber
    \begin{split}
     &\tilde{\bold{c}}=\theta_{\bold{\lambda}}^{-1}\bold{c}=(\bold{a},\bold{b},w,z)\in \theta_{\bold{\lambda}}^{-1}H;
     \\&\bold{c}'=(\bold{a},\bold{b})\in\mathbb{R}^{2s}.
    \end{split}
  \end{equation}
In other words, $\tilde{\bold{c}}$ is $\bold{c}$ written in the new coordinate system, and $\bold{c}'$ denotes the first $2s$ coordinates of $\bold{c}$.

Let $Y=H/(H\cap\Gamma_{0})$ be a submanifold of $H_{0}$. If $H$ is of type 1, an integer vector $ old{k}\in\mathbb{Z}^{2}$ is called an \emph{$S$-frequency} of $H$ if $ old{k}=(k,k)$ for some $k
eq 0$. If $H$ is of type 2, an integer $k\in\mathbb{Z}$ is called an \emph{$S$-frequency} of $H$ if $k
eq 0$. An \emph{$S$-frequency nilcharacter} of $H$ is a nilcharacter whose frequency is an $S$-frequency of $H$. Let $N\in\mathbb{N}$ and $\epsilon>0$. A sequence $g\colon [N]ightarrow Y$ is \emph{$S$-totally $\epsilon$-equidistrbuted} if for any $S$-frequency nilcharacter (of $H$) $f$ with $f\in Lip(Y)$, $\Vert f\Vert_{Lip(Y)}\leq 1$, and any arithmetic progression $P\subset[N]$, we have that  egin{equation}
onumber  egin{split} \Bigl\vert\mathbb{E}_{n\in[N]} old{1}_{P}(n)f(g(n)\cdot e_{Y})\Bigr\vert<\epsilon. \end{split} \end{equation}

(1) Suppose $\Phi$ is a nilcharacter of frequency $k
eq 0$ of $G$. Then $\Phi(g\cdot x)=e(k\cdot g)\Phi(x)$ for all $g\in G_{2}$ and $x\in G/(G\cap\Gamma)$. So  egin{equation}
onumber  egin{split} &\qquad\Phi\otimes\overline{\Phi}((g,g')\cdot (x,x'))=\Phi(g\cdot x)\overline{\Phi}(g'\cdot x') \&=e(k\cdot g-k\cdot g')\Phi(x)\overline{\Phi}(x') =e\Bigl((k,-k)\cdot(g,g')\Bigr)\Phi\otimes\overline{\Phi}(x,x') \end{split} \end{equation} for all $g,g'\in G_{2}$ and $x,x'\in G/(G\cap\Gamma)$. So $\Psi=\Phi\otimes\overline{\Phi}$ is a nilcharacter of frequency $(k,-k)$ of $G	imes G$. (2) If $H$ and $H'$ are both of type 1 or both of type 2, then $[H,H]=[H',H']$. Suppose $f$ is a nilcharacter of frequency $ old{k}$ on $H$. Then $f(g\cdot x)=e( old{k}\cdot g)f(x)$ for all $g\in[H,H]$ and $x\in H/(H\cap\Gamma)$, where the product $ old{k}\cdot g$ is taken as the inner product on $[H,H]$. So $f(g\cdot x)=e( old{k}\cdot g)f(x)$ for all $x\in H'/(H'\cap\Gamma)\subset H/(H\cap\Gamma)$ and $g\in [H,H]=[H',H']$. So $f|_{H'}$ is also a nilcharacter of frequency $ old{k}$, which finishes the proof. (3) Suppose $f$ is a nilcharacter of frequency $ old{k}=(k,-k)$ on $H$ ($k
eq 0$). Then $f(g\cdot x)=e( old{k}\cdot g)f(x)=e(k(a-b))f(x)$ for all $g=( old{0},a; old{0},b)\in[H,H]$ and $x\in H/(H\cap\Gamma)$. Since $H'$ is $(\lambda_{1},\lambda_{2})$-shaped, every $h\in [H',H']$ can be written as $h=( old{0},\lambda_{1} a; old{0},\lambda_{2}a)$. So  egin{equation}
onumber  egin{split} f(h\cdot x)=e( old{k}\cdot h)f(x)=e(k(\lambda_{1}-\lambda_{2})a)f(x) \end{split} \end{equation} for all $x\in Y'=H'/(H'\cap\Gamma)$. So $f|_{Y'}$ is an $S$-frequency character on $Y'$ if and only if $\lambda_{1}
eq\lambda_{2}$, which finishes the proof.

(1) Suppose $\Phi$ is a nilcharacter of frequency $k\neq 0$ of $G$. Then $\Phi(g\cdot x)=e(k\cdot g)\Phi(x)$ for all $g\in G_{2}$ and $x\in G/(G\cap\Gamma)$. So
  \begin{equation}\nonumber
    \begin{split}
      &\qquad\Phi\otimes\overline{\Phi}((g,g')\cdot (x,x'))=\Phi(g\cdot x)\overline{\Phi}(g'\cdot x')
      \\&=e(k\cdot g-k\cdot g')\Phi(x)\overline{\Phi}(x')
=e\Bigl((k,-k)\cdot(g,g')\Bigr)\Phi\otimes\overline{\Phi}(x,x')
    \end{split}
  \end{equation}
for all $g,g'\in G_{2}$ and $x,x'\in G/(G\cap\Gamma)$. So $\Psi=\Phi\otimes\overline{\Phi}$ is a nilcharacter of frequency $(k,-k)$ of $G\times G$.

(3) Suppose $f$ is a nilcharacter of frequency $\bold{k}=(k,-k)$ on $H$ ($k\neq 0$). Then $f(g\cdot x)=e(\bold{k}\cdot g)f(x)=e(k(a-b))f(x)$ for all $g=(\bold{0},a;\bold{0},b)\in[H,H]$ and  $x\in H/(H\cap\Gamma)$. Since $H'$ is $(\lambda_{1},\lambda_{2})$-shaped, every $h\in [H',H']$ can be written as $h=(\bold{0},\lambda_{1} a;\bold{0},\lambda_{2}a)$. So
    \begin{equation}\nonumber
    \begin{split}
   f(h\cdot x)=e(\bold{k}\cdot h)f(x)=e(k(\lambda_{1}-\lambda_{2})a)f(x)
    \end{split}
  \end{equation}
  for all $x\in Y'=H'/(H'\cap\Gamma)$. So $f|_{Y'}$ is an $S$-frequency character on $Y'$ if and only if $\lambda_{1}\neq\lambda_{2}$, which finishes the proof.

Since $ old{k}$ is of the same type as $H$, it is easy to see that $H_{2}\subset H^{\underline{ old{k}}}$. In the proof, $C_{1},C_{2}$ are constants depending only on $X,C,\kappa$ and $d$. We assume without loss of generality that $g_{1}(n)$ has no constant term, i.e. we assume $g_{1}(n)=\prod_{i=1}^{d}\alpha_{i}^{ inom{n}{i}}$. Let $F_{0}\subset H$ be a bounded fundamental domain of the projection $Hightarrow Y$ (we assume $F_{0}$ is fixed given $Y$). Then by Lemma ef{cts}, there exists $C_{1}>0$ such that  egin{equation}
