   \end{split}
 \end{equation}
for all $h\in F_{2}$ and $y,z\in Y$.

Since $\bold{k}=p\underline{\bold{k}}$,
 we have that $\Vert\underline{\bold{k}}\cdot\tilde{\alpha_{i}^{p}}\Vert_{\mathbb{R}/\mathbb{Z}}
 =\Vert\bold{k}\cdot\tilde{\alpha_{i}}\Vert_{\mathbb{R}/\mathbb{Z}}\leq\frac{C}{N^{i}}$ for $1\leq i\leq d-1$. So there exist $C_{2}>0$ and $\omega_{1},\dots,\omega_{d-1}\in H$ such that for all $1\leq i\leq d-1$, $\underline{\bold{k}}\cdot\tilde{(\omega_{i}^{-1}\alpha_{i}^{p})}\in\mathbb{Z}$ and
 \begin{equation}\nonumber
   \begin{split}
