   \end{split}
 \end{equation}
 Since the entries of $\underline{\bold{k}}$ are relatively prime integers, we deduce that there exist $\gamma_{1},\dots,\gamma_{d-1}\in\Gamma\times\Gamma$ such that
 $\underline{\bold{k}}\cdot\tilde{(\omega_{i}^{-1}\alpha_{i}^{p}\gamma_{i}^{-1})}=0$ for all $1\leq i\leq d-1$. In other words,
 \begin{equation}\nonumber
    \begin{split}
     \alpha'_{i}\coloneqq \omega_{i}^{-1}\alpha_{i}^{p}\gamma_{i}^{-1}\in H^{\underline{\bold{k}}}, \text{ for all } 1\leq i\leq d-1.
    \end{split}
  \end{equation}

By assumption, there exists an $S$-frequency nilcharacter $f$ with $\Vert f\Vert_{Lip(H)}\leq 1$ such that
   \begin{equation} \begin{split}
