  \end{equation}

Since $\Vert\Psi''|_{Y}\Vert_{Lip(Y)}\leq\Vert\Psi''|_{Y}\Vert_{\mathcal{C}^{2m}(Y)}\leq H(M)^{2}$,
$(g'(m,n)\cdot e_{Y})_{(m,n)\in[\tilde{N}]\times[\tilde{N}]}$ is not totally $\frac{\delta_{1}(M)}{16H(M)^{2}}$-equidistributed in $Y$.
This contradicts the fact that $(g'(m,n)\cdot e_{Y})_{(m,n)\in[\tilde{N}]\times[\tilde{N}]}$ is totally $\tilde{\sigma}(M)$-equidistributed in $Y$. Therefore, $\Vert\chi_{N,u}\Vert_{U^{3}(R_{\tilde{N}})}\leq\epsilon$, completing the proof of Theorem \ref{nU3w}.

Suppose on the contrary that (iii) does not hold, then
  \begin{equation}\nonumber
   \begin{split}
   \Vert\chi_{N,u}\Vert_{U^{3}(R_{\tilde{N}})}>\epsilon.
   \end{split}
  \end{equation}
By the choice of $\theta_{1}$ and Corollary \ref{mIU3}, there exist a nilmanifold $X=G/\Gamma$ of order 2 belonging to the family $\mathcal{H}$, a nilcharacter $\Psi$ on $X$ with frequency 1, and a polynomial map $g\colon\mathbb{Z}^{2}\rightarrow G$ of degree at most 2, such that $\Vert\Psi\Vert_{\mathcal{C}^{2m}(X)}\leq 1$ and
  \begin{equation}\nonumber
   \begin{split}
   \Bigl\vert\mathbb{E}_{\alpha=a+bi\in R_{\tilde{N}}}\chi_{N,u}(\alpha)\Psi(g(a,b)\cdot e_{X})\Bigr\vert\geq\delta,
   \end{split}
  \end{equation}
  where $m$ is the dimension of $X$.

Applying Corollary \ref{mF} to $(g(m,n))_{(m,n)\in [\tilde{N}]\times[\tilde{N}]}$ and $\omega, M_{0}, M_{1}$ defined in the previous subsection, we get an integer $M_{0}\leq M\leq M_{1}$, a nilmanifold $X'=G'/\Gamma'$ belonging to the family $\mathcal{F}(M,X)$, and a factorization
    \begin{equation}\nonumber
   \begin{split}
   g(m,n)=\epsilon(m,n)g'(m,n)\gamma(m,n)
   \end{split}
  \end{equation}
  into sequences satisfying Properties (i)-(v) of Corollary \ref{mF}. From now on, we work with this specifically chosen $M$. Note that $M$ is bounded below and above by constants depending only on $\epsilon$.

Denote $L=\lfloor\frac{\delta\tilde{N}}{8M^{2}}\rfloor$. By Property (v) of Corollary \ref{mF}, we can partition $[\tilde{N}]\times[\tilde{N}]$ into products of arithmetic progressions of step $p_{1}$ and $p_{2}$ and of size $L\times L$ for some $p_{1},p_{2}\leq M$, and a leftover set of size $C\delta/M$ which can be ignored (upon replacing $\delta$ with $\delta/2$ below) such that $\gamma(m,n)$ is a constant on each piece. So there exists a product of arithmetic progressions $P$ of step $p_{1}$ and $p_{2}$ and of size $L\times L$ such that
  \begin{equation}\nonumber
   \begin{split}
   \Bigl\vert\mathbb{E}_{(m,n)\in [\tilde{N}]\times[\tilde{N}]}\bold{1}_{P}(m,n)\chi_{N,u}(m+ni)\Psi(g(m,n)\cdot e_{X})\Bigr\vert\geq\frac{\delta L^{2}}{2\tilde{N}^{2}}\geq
   \frac{\delta^{3}}{128M^{4}}-\frac{\delta^{2}}{8M^{2}\tilde{N}}.
   \end{split}
  \end{equation}

Pick $(m,n),(m_{0},n_{0})\in P$. By the right invariance of $d_{G}$ and the $(M,(\tilde{N},\tilde{N}))$-smoothness of $(\epsilon(m,n))_{(m,n)\in R_{\tilde{N}}}$, we have that
  \begin{equation}\nonumber
   \begin{split}
   &\qquad d_{G}(g(m,n),\epsilon(m_{0},n_{0})g'(m,n)\gamma(m_{0},n_{0}))\leq d_{G}(\epsilon(m,n),\epsilon(m_{0},n_{0}))
   \\&\leq (p_{1}+p_{2})L\frac{\sqrt{2}M}{\tilde{N}}\leq \frac{2\sqrt{2}M^{2}L}{\tilde{N}}.
   \end{split}
  \end{equation}
  Then
  \begin{equation}\nonumber
   \begin{split}
   \Bigl\vert\Psi(g(m,n)\cdot e_{X})-\Psi(\epsilon(m_{0},n_{0})g'(m,n)\gamma(m_{0},n_{0})\cdot e_{X})\Bigr\vert\leq \frac{2\sqrt{2}M^{2}L}{\tilde{N}}.
   \end{split}
  \end{equation}
Thus
  \begin{equation}\nonumber
   \begin{split}
   &\qquad\mathbb{E}_{(m,n)\in [\tilde{N}]\times[\tilde{N}]}\bold{1}_{P}(m,n)\Bigl\vert\chi_{N,u}(m+ni)\Bigr\vert\cdot\Bigl\vert\Psi(g(m,n)\cdot e_{X})
   -\Psi(\epsilon(m_{0},n_{0})g'(m,n)\gamma(m_{0},n_{0}))\cdot e_{X})\Bigr\vert
   \\&\leq
   \frac{L^{2}}{\tilde{N}^{2}}\frac{2\sqrt{2}M^{2}L}{\tilde{N}}\leq\frac{\delta^{3}}{256M^{4}}.
   \end{split}
  \end{equation}
  So we deduce that
  \begin{equation} \begin{split}
   \Bigl\vert\mathbb{E}_{(m,n)\in [\tilde{N}]\times[\tilde{N}]}\bold{1}_{P}(m,n)\chi_{N,u}(m+ni)\Psi(\epsilon(m_{0},n_{0})g'(m,n)\gamma(m_{0},n_{0})\cdot e_{X})\Bigr\vert\geq\frac{\delta^{3}}{257M^{4}}=\delta_{1}(M)
  \end{split}
  \end{equation}
  provided that $N$ is sufficiently large depending on $\epsilon$.

Since $\gamma(m_{0},n_{0})$ is $M$-rational, there exists $h_{0}\in\Sigma(M,X)$ such that $\gamma(m_{0},n_{0})\cdot e_{X}=h_{0}\cdot e_{X}$. Let
$e_{Y}=h_{0}\cdot e_{X}, Y=G'\cdot e_{Y}\cong G'/(h_{0}\Gamma h_{0}^{-1}\cap G'), \Psi'(x)=\Psi(\epsilon(m_{0},n_{0})\cdot x)$. Note that $Y$ belongs to the family $\mathcal{F}'$. For every $m,n\in\mathbb{N}$, we have that
\begin{equation}\nonumber
   \begin{split}
   \Psi(\epsilon(m_{0},n_{0})g'(m,n)\gamma(m_{0},n_{0})\cdot e_{X})=\Psi'(g'(m,n)\cdot e_{Y}),
  \end{split}
  \end{equation}
  and by (\ref{temp1}), we deduce that
  \begin{equation} \begin{split}
   \Bigl\vert\mathbb{E}_{(m,n)\in [\tilde{N}]\times[\tilde{N}]}\bold{1}_{P}(m,n)\chi_{N,u}(m+ni)\Psi'(g'(m,n)\cdot e_{Y})\Bigr\vert\geq\delta_{1}(M).
  \end{split}
  \end{equation}

Since $(\epsilon(m,n))_{(m,n)\in R_{\tilde{N}}}$ is $(M,(\tilde{N},\tilde{N}))$-smooth, we have that $d_{G}(\epsilon(m_{0},n_{0}),\bold{1}_{G})\leq M$. Furthermore, since $\Vert\Psi\Vert_{\mathcal{C}^{2m}(X)}\leq 1$, by the choice of $H(M)$ (property (ii)), $\Vert\Psi'\Vert_{\mathcal{C}^{2m}(X)}\leq H(M)$.
Thus (property (iv))
\begin{equation}\nonumber
   \begin{split}
   \Vert\Psi'|_{Y}\Vert_{\mathcal{C}^{2m}(Y)}\leq H(M)^{2}.
  \end{split}
  \end{equation}
Recall that $(g'(m,n)\cdot e_{X})_{(m,n)\in[\tilde{N}]\times[\tilde{N}]}$ is totally $\omega(M)$-equidistributed in $X$, and by the definition of $\omega$ and $\rho$, we deduce that $(g'(m,n)\cdot e_{Y})_{(m,n)\in[\tilde{N}]\times[\tilde{N}]}$ is totally $\tilde{\sigma}(M)$-equidistributed in $Y$.

Let $z=\int_{\mathbb{T}^{m}}\Psi'\circ\psi dm$ and $\Psi''=\Psi'-z$. By Lemma \ref{1p}, we get that
\begin{equation}\nonumber
   \begin{split}
   \Bigl\vert\mathbb{E}_{(m,n)\in [\tilde{N}]\times[\tilde{N}]}\bold{1}_{P}(m,n)z\chi_{N,u}(m+ni)\Bigr\vert
   \leq c_{1}\Vert\chi_{N,u}\Vert_{U^{2}(R_{\tilde{N}})}\leq c_{1}\theta_{1}=c_{1}\theta(M_{1})\leq \delta_{1}(M_{1})/2\leq \delta_{1}(M)/2.
  \end{split}
  \end{equation}
  Thus by (\ref{temp2}), we have that
  \begin{equation} \begin{split}
   \Bigl\vert\mathbb{E}_{(m,n)\in [\tilde{N}]\times[\tilde{N}]}\bold{1}_{P}(m,n)\chi_{N,u}(m+ni)\Psi''(g'(m,n)\cdot e_{Y})\Bigr\vert\geq\delta_{1}(M)/2,
  \end{split}
  \end{equation}
where
  \begin{equation}\nonumber
   \begin{split}
   \Vert\Psi''|_{Y}\Vert_{\mathcal{C}^{2m}(Y)}\leq H(M)^{2}, \int_{\mathbb{T}^{m}}\Psi''\circ\phi dm =0.
  \end{split}
  \end{equation}

Recall that $\chi_{N,s}=\chi_{N}*\psi'$, where $\psi'$ is a kernel of $R_{\tilde{N}}$. So we may write $\chi_{N,u}=\chi_{N}*\psi$
for some function $\psi$ on $R_{\tilde{N}}$. Since $\mathbb{E}_{\alpha\in R_{\tilde{N}}}\psi'(\alpha)=1$, we have that $\mathbb{E}_{\alpha\in R_{\tilde{N}}}\vert\psi'(\alpha)\vert\leq 2$.
We deduce from (\ref{temp3}) that there exists $(m',n')\in [\tilde{N}]\times[\tilde{N}]$ such that
  \begin{equation}\nonumber
   \begin{split}
   &\Bigl\vert\mathbb{E}_{(m,n)\in [\tilde{N}]\times[\tilde{N}]}\bold{1}_{P}((m+m',n+n')\mod [\tilde{N}]\times[\tilde{N}])
   \\&\cdot\chi_{N}(m+ni)\Psi''(g'((m+m',n+n')\mod [\tilde{N}]\times[\tilde{N}])\cdot e_{Y})\Bigr\vert\geq\delta_{1}(M)/4,
  \end{split}
  \end{equation}
  where the residue class $(m+m',n+n')\mod [\tilde{N}]\times[\tilde{N}]$ is taken in $[1,\tilde{N}]\times[1,\tilde{N}]$ instead of the more usual set $[0,\tilde{N}-1]\times[0,\tilde{N}-1]$. Then the average
  \begin{equation}\nonumber
   \begin{split}
   \Bigl\vert\mathbb{E}_{(m,n)\in [\tilde{N}]\times[\tilde{N}]}\bold{1}_{P}(m+m'',n+n'')\bold{1}_{J}(m,n)\bold{1}_{[N]\times[N]}(m,n)\chi(m+ni)\Psi''(g'(m+m'',n+n'')\cdot e_{Y})\Bigr\vert
  \end{split}
  \end{equation}
    is at least $\delta_{1}(M)'/16$, where the pair $(J,(m'',n''))$ is one of the following 4 combinations:

  (i) $J=[\tilde{N}-m']\times[\tilde{N}-n'], m''=m', n''=n'$;

  (ii) $J=[\tilde{N}-m']\times(\tilde{N}-n',\tilde{N}], m''=m', n''=n'-\tilde{N}$;

  (iii) $J=(\tilde{N}-m',\tilde{N}]\times[\tilde{N}-n'], m''=m'-\tilde{N}, n''=n'$;

  (iv) $J=(\tilde{N}-m',\tilde{N}]\times(\tilde{N}-n',\tilde{N}], m''=m'-\tilde{N}, n''=n'-\tilde{N}$.

Recall that $\chi_{N,s}=\chi_{N}*\psi'$, where $\psi'$ is a kernel of $R_{\tilde{N}}$. So we may write $\chi_{N,u}=\chi_{N}*\psi$
for some function $\psi$ on $R_{\tilde{N}}$. Since $\mathbb{E}_{\alpha\in R_{\tilde{N}}}\psi'(\alpha)=1$, we have that $\mathbb{E}_{\alpha\in R_{\tilde{N}}}\vert\psi'(\alpha)\vert\leq 2$.
We deduce from (\ref{temp3}) that there exists $(m',n')\in [\tilde{N}]\times[\tilde{N}]$ such that
  \begin{equation}\nonumber
   \begin{split}
   &\Bigl\vert\mathbb{E}_{(m,n)\in [\tilde{N}]\times[\tilde{N}]}\bold{1}_{P}((m+m',n+n')\mod [\tilde{N}]\times[\tilde{N}])
   \\&\cdot\chi_{N}(m+ni)\Psi''(g'((m+m',n+n')\mod [\tilde{N}]\times[\tilde{N}])\cdot e_{Y})\Bigr\vert\geq\delta_{1}(M)/4,
  \end{split}
  \end{equation}
  where the residue class $(m+m',n+n')\mod [\tilde{N}]\times[\tilde{N}]$ is taken in $[1,\tilde{N}]\times[1,\tilde{N}]$ instead of the more usual set $[0,\tilde{N}-1]\times[0,\tilde{N}-1]$. Then the average
  \begin{equation}\nonumber
   \begin{split}
   \Bigl\vert\mathbb{E}_{(m,n)\in [\tilde{N}]\times[\tilde{N}]}\bold{1}_{P}(m+m'',n+n'')\bold{1}_{J}(m,n)\bold{1}_{[N]\times[N]}(m,n)\chi(m+ni)\Psi''(g'(m+m'',n+n'')\cdot e_{Y})\Bigr\vert
  \end{split}
  \end{equation}
    is at least $\delta_{1}(M)'/16$, where the pair $(J,(m'',n''))$ is one of the following 4 combinations:

Note that $\bold{1}_{P}(m+m'',n+n'')\bold{1}_{J}(m,n)\bold{1}_{[N]\times[N]}(m,n)=\bold{1}_{P'}(m,n)$ for some $P'$ which is a product of arithmetic progressions. So
    \begin{equation}\nonumber
   \begin{split}
   \Bigl\vert\mathbb{E}_{(m,n)\in [\tilde{N}]\times[\tilde{N}]}\bold{1}_{P'}(m,n)\chi(m+ni)\Psi''(g'(m+m'',n+n'')\cdot e_{Y})\Bigr\vert\geq\delta_{1}(M)/16.
  \end{split}
  \end{equation}

By a similar argument as Proposition 10.5 in ~\cite{FH}, we have that
   \begin{equation}\nonumber
  \begin{split}
    \liminf_{N\rightarrow\infty}\mathbb{E}_{(\alpha,\beta)\in\Theta_{N}}\int_{\mathcal{M}_{\mathbb{Z}[i]}}{\chi_{N,s}(\alpha+\gamma_{1}\beta)\chi_{N,s}(\alpha+\gamma_{2}\beta)\overline{\chi_{N,s}}(\alpha+\gamma_{3}\beta)
    \overline{\chi_{N,s}}(\alpha+\gamma_{4}\beta)}d\nu(\chi)
  \end{split}
  \end{equation}
is bounded below by a positive number which is independent of $\epsilon$.

It then suffices to show that all terms containing the expression $\chi_{N,u}$ are negligible, which holds immediately if one can show that
      \begin{equation} \begin{split}
      \Bigl\vert\mathbb{E}_{\alpha,\beta\in R_{\tilde{N}}}\bold{1}_{R_{N}}(\beta)\prod_{j=0}^{3}a_{j}(\alpha+\gamma_{j}\beta)\Bigr\vert
      \leq C\min_{1\leq j\leq 4}(\Vert a_{j}\Vert_{U^{3}(R_{\tilde{N}})})^{1/3}+\frac{10}{\tilde{N}}
    \end{split}
  \end{equation}
for all functions $a_{1},\dots,a_{4}$ on $R_{\tilde{N}}$ with $\Vert a_{j}\Vert_{L^{\infty}(R_{\tilde{N}})}\leq 1$ for $j=1,\dots,4$, where $C>0$ depends only on $\gamma_{1},\dots,\gamma_{4}$ (the exponent on the right hand side of (\ref{temp8}) is $\frac{1}{2}$ for the 1-dimensional case and is $\frac{1}{3}$ for the 2-dimensional case).
